package com.nextaicommerce.platform.sync;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.transaction.support.*;
import tools.jackson.databind.ObjectMapper;
class FbaInventoryRefreshTest {
 JdbcTemplate jdbc=mock(JdbcTemplate.class);TransactionTemplate tx=mock(TransactionTemplate.class);ApplicationEventPublisher events=mock(ApplicationEventPublisher.class);ObjectMapper json=new ObjectMapper();UUID tenant=UUID.randomUUID(),store=UUID.randomUUID(),job=UUID.randomUUID(),run=UUID.randomUUID(),source=UUID.randomUUID();FbaInventoryRefresh refresh;
 @BeforeEach void setup(){when(tx.execute(any())).thenAnswer(i->((org.springframework.transaction.support.TransactionCallback<?>)i.getArgument(0)).doInTransaction(new SimpleTransactionStatus()));refresh=new FbaInventoryRefresh(jdbc,tx,events,json,true);}
 @Test void disabledCannotEnqueue(){var disabled=new FbaInventoryRefresh(jdbc,tx,events,json,false);assertThatThrownBy(()->disabled.request(tenant,store)).isInstanceOf(IllegalStateException.class);verifyNoInteractions(jdbc,events);}
 @Test void publicationWithoutLiveScopedLeaseDoesNothing(){when(jdbc.queryForList(anyString(),eq(UUID.class),any(),any(),any(),any())).thenReturn(List.of());assertThatThrownBy(()->refresh.publish(new FbaInventoryRefresh.Request(tenant,store,job),"US",new FbaInventorySnapshotTest().pages())).isInstanceOf(IllegalStateException.class);verify(jdbc,never()).update(anyString(),any(Object[].class));}
 @SuppressWarnings({"rawtypes","unchecked"}) void active(boolean live){when(jdbc.query(anyString(),any(RowMapper.class),eq(tenant),eq(store))).thenAnswer(i->i.getArgument(0,String.class).startsWith("SELECT marketplace_identifier")?List.of("US"):Collections.singletonList(new Object[]{job,Timestamp.from(Instant.now().plusSeconds(live?900:-1)),"FBA_MANUAL"}));}
 @Test void repeatedRequestCoalescesSameJob(){active(true);assertThat(refresh.request(tenant,store)).isEqualTo(job);verify(jdbc,never()).update(anyString(),any(Object[].class));verify(jdbc,never()).queryForObject(startsWith("INSERT"),eq(UUID.class),any(Object[].class));}
 @Test void expiredRequestIsRetiredBeforeNewJob(){active(false);UUID next=UUID.randomUUID();when(jdbc.queryForObject(startsWith("INSERT INTO marketplace_sync_runs"),eq(UUID.class),eq(tenant),eq(store))).thenReturn(run);when(jdbc.queryForObject(startsWith("INSERT INTO marketplace_sync_jobs"),eq(UUID.class),eq(tenant),eq(store),eq(run),anyString())).thenReturn(next);assertThat(refresh.request(tenant,store)).isEqualTo(next);verify(jdbc).update(contains("Previous inventory read expired"),eq(tenant),eq(job));}
 void publishable(){when(jdbc.queryForList(anyString(),eq(UUID.class),eq(tenant),eq(store),eq(job),eq("US"))).thenReturn(List.of(job));when(jdbc.queryForObject(startsWith("INSERT INTO amazon_source_documents"),eq(UUID.class),eq(tenant),eq(store),eq(job),anyString(),anyString(),eq(1))).thenReturn(source);}
 @Test void publishesOnlyInventoryAndProvenanceThenCompletes(){publishable();assertThat(refresh.publish(new FbaInventoryRefresh.Request(tenant,store,job),"US",new FbaInventorySnapshotTest().pages())).isEqualTo(1);var calls=mockingDetails(jdbc).getInvocations().stream().filter(i->i.getMethod().getName().equals("update")).map(i->i.getArgument(0,String.class)).toList();assertThat(calls).anyMatch(s->s.startsWith("INSERT INTO amazon_inventory_snapshots")).anyMatch(s->s.contains("status='COMPLETED'"));assertThat(calls).noneMatch(s->s.contains("inventory_ledger")||s.contains("reservation")||s.contains("amazon_orders")||s.contains("marketplace_connections"));}
 @Test void persistenceFailureDoesNotCompleteJob(){publishable();doThrow(new org.springframework.dao.DataIntegrityViolationException("fixture")).when(jdbc).update(startsWith("INSERT INTO amazon_inventory_snapshots"),any(Object[].class));assertThatThrownBy(()->refresh.publish(new FbaInventoryRefresh.Request(tenant,store,job),"US",new FbaInventorySnapshotTest().pages())).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);verify(jdbc,never()).update(contains("status='COMPLETED'"),any(Object[].class));}
 @Test void incompleteReadCannotEvenClaimPublication(){var pages=new FbaInventorySnapshotTest().pages();((tools.jackson.databind.node.ObjectNode)pages.get(0).path("response")).putObject("pagination").put("nextToken","more");assertThatThrownBy(()->refresh.publish(new FbaInventoryRefresh.Request(tenant,store,job),"US",pages)).isInstanceOf(IllegalArgumentException.class);verifyNoInteractions(jdbc);}
 @Test void workerUsesOnlyDetailedInventoryGetAndRecomputesAfterPublish(){var service=mock(FbaInventoryRefresh.class);var amazon=mock(AmazonSpApiClient.class);var forecasts=mock(com.nextaicommerce.platform.fba.FbaReplenishmentForecasts.class);var request=new FbaInventoryRefresh.Request(tenant,store,job);when(service.claim(request)).thenReturn("ATVPDKIKX0DER");var response=new FbaInventorySnapshotTest().pages().get(0).path("response");when(amazon.getAt(eq(tenant),eq(store),eq("https://sellingpartnerapi-na.amazon.com"),contains("details=true&granularityType=Marketplace"))).thenReturn(new AmazonSpApiClient.ApiResponse(200,"request",response,response.toString(),null));new FbaInventoryRefreshWorker(service,amazon,json,forecasts).read(request);var order=inOrder(service,forecasts);order.verify(service).claim(request);order.verify(service).publish(eq(request),eq("ATVPDKIKX0DER"),any());order.verify(forecasts).refresh(tenant,store);verify(amazon).getAt(eq(tenant),eq(store),anyString(),startsWith("/fba/inventory/v1/summaries?"));verifyNoMoreInteractions(amazon);}
}
